-- =============================================================================
-- School Store — complete database setup (generated by `npm run db:bundle`)
-- =============================================================================
-- HOW TO USE: Supabase → SQL Editor → New query → paste ALL of this → Run.
-- Run it only ONCE, on a new project. Don't edit this file; edit the files in
-- supabase/migrations/ and regenerate it instead.
-- Includes SAMPLE DATA (fake products, orders and sales) for testing.
-- =============================================================================

-- Stop if the store tables already exist, so nothing gets created twice.
do $$
begin
  if to_regclass('public.products') is not null then
    raise exception 'The store database is already set up. Nothing was changed.';
  end if;
end $$;

-- >>>>>>>>>>>>>>>>>>>>>>>> 20261026000001_schema.sql >>>>>>>>>>>>>>>>>>>>>>>>
-- =============================================================================
-- School Store — database schema
-- =============================================================================
-- How this file is organized:
--   1. Types (enums)
--   2. Tables
--   3. Helper functions (today in Arizona, is_admin, reserved stock)
--   4. Triggers (keep products.stock in sync with the stock ledger)
--
-- Conventions used everywhere:
--   * Money is stored as whole CENTS in integer columns (price_cents = 150 means
--     $1.50). Decimals cause rounding bugs; integers don't.
--   * Every stock change is a row in `stock_movements`. Never edit
--     products.stock directly — insert a movement and the trigger updates it.
--   * "Today" means today in the store's timezone (America/Phoenix), not UTC.
-- =============================================================================


-- -----------------------------------------------------------------------------
-- 1. Types
-- -----------------------------------------------------------------------------

-- Order life cycle. Open statuses (received, preparing, ready) reserve stock.
create type public.order_status as enum (
  'received',   -- student placed it
  'preparing',  -- staff is bagging it
  'ready',      -- waiting at the pickup spot
  'picked_up',  -- student paid at pickup (stock is subtracted now)
  'canceled',   -- canceled by staff
  'no_show',    -- staff marked it as never collected
  'expired'     -- automatically closed at the end of the pickup day
);

-- Why stock changed. Shown in the inventory history.
create type public.movement_reason as enum (
  'initial',            -- starting stock when a product is created
  'restock',            -- added by a shopping trip (expense)
  'online_pickup',      -- online order picked up and paid
  'online_pickup_undo', -- a picked-up order was moved back to another status
  'sale_import',        -- in-person sales from the InTouchPay import
  'manual_adjustment',  -- staff fixed the count by hand (note required)
  'spoilage'            -- thrown away / expired (note required)
);

create type public.payment_type as enum ('cash', 'debit', 'other');


-- -----------------------------------------------------------------------------
-- 2. Tables
-- -----------------------------------------------------------------------------

-- The one admin account. Being logged in is NOT enough to see staff data:
-- the user's id must also be in this table. That way, even if someone found
-- a way to create a Supabase account, they would see nothing.
create table public.admins (
  user_id    uuid primary key references auth.users (id) on delete cascade,
  created_at timestamptz not null default now()
);

-- Store-wide settings. There is exactly one row (id = 1).
create table public.settings (
  id                         int primary key default 1 check (id = 1),
  store_name                 text not null default 'School Store',
  store_hours                text not null default 'Mon–Fri, before school through 7th hour',
  pickup_location            text not null default 'Store window by the cafeteria',
  banner_text                text,               -- optional announcement on the menu
  timezone                   text not null default 'America/Phoenix',
  -- Ordering rules
  order_cutoff_time          time not null default '14:00', -- no more same-day orders after this
  order_lead_minutes         int  not null default 20 check (order_lead_minutes between 0 and 240),
  max_orders_per_student_day int  not null default 2  check (max_orders_per_student_day between 1 and 20),
  max_items_per_order        int  not null default 10 check (max_items_per_order between 1 and 50),
  max_orders_per_hour_per_device int not null default 5 check (max_orders_per_hour_per_device between 1 and 100),
  -- Privacy
  order_retention_days       int  not null default 90 check (order_retention_days between 7 and 730),
  -- Inventory math (see src/lib/calculations.ts)
  sales_average_days         int  not null default 28 check (sales_average_days between 7 and 180),
  reorder_buffer_days        int  not null default 2  check (reorder_buffer_days between 0 and 30),
  shopping_interval_days     int  not null default 7  check (shopping_interval_days between 1 and 60),
  next_shopping_date         date,
  updated_at                 timestamptz not null default now()
);
insert into public.settings (id) values (1);

-- Pickup windows students can choose at checkout.
-- `starts_at` is when the window happens (e.g. the end of 1st hour).
-- Orders for a window close `order_lead_minutes` before it starts.
create table public.pickup_windows (
  id         serial primary key,
  label      text not null,
  starts_at  time not null,
  sort_order int  not null default 0,
  active     boolean not null default true
);

-- Days the store is closed (holidays, breaks, testing days). Weekends are
-- always closed and don't need to be listed.
create table public.closed_dates (
  closed_on date primary key,
  reason    text
);

create table public.suppliers (
  id         uuid primary key default gen_random_uuid(),
  name       text not null unique,
  notes      text,
  created_at timestamptz not null default now()
);

create table public.products (
  id               uuid primary key default gen_random_uuid(),
  name             text not null,
  description      text,
  category         text not null default 'Snacks',
  emoji            text,                 -- shown when there is no photo yet
  photo_path       text,                 -- path inside the "product-photos" bucket
  price_cents      int  not null check (price_cents >= 0),
  unit_cost_cents  int  not null default 0 check (unit_cost_cents >= 0),
  stock            int  not null default 0,  -- kept in sync by stock_movements; can go negative if counts are off
  reorder_point    int  not null default 10 check (reorder_point >= 0),
  lead_days        int  not null default 2  check (lead_days >= 0), -- days between noticing and restocking
  supplier_id      uuid references public.suppliers (id) on delete set null,
  is_perishable    boolean not null default false,
  available_online boolean not null default true,
  archived         boolean not null default false,
  tags             text[] not null default '{}',  -- e.g. {new, limited}
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now()
);
create index on public.products (archived, category);

-- Names the InTouchPay export uses for a product ("HOT CHEETOS 1OZ").
-- Stored lowercase and trimmed so matching ignores case and extra spaces.
create table public.product_aliases (
  id         uuid primary key default gen_random_uuid(),
  product_id uuid not null references public.products (id) on delete cascade,
  alias      text not null unique check (alias = lower(btrim(alias)) and alias <> ''),
  created_at timestamptz not null default now()
);

-- Online orders. Only first name, last name and grade are collected.
create sequence public.order_number_seq start 1;

create table public.orders (
  id               uuid primary key default gen_random_uuid(),
  order_number     int  not null unique default nextval('public.order_number_seq'),
  first_name       text not null check (char_length(first_name) between 1 and 40),
  last_name        text not null check (char_length(last_name)  between 1 and 40),
  grade            text not null check (char_length(grade) between 1 and 20),
  pickup_window_id int  not null references public.pickup_windows (id),
  pickup_date      date not null,
  status           public.order_status not null default 'received',
  total_cents      int  not null check (total_cents >= 0),
  staff_notes      text,
  ip_hash          text,  -- one-way hash of the device's IP, only used for rate limiting
  created_at       timestamptz not null default now(),
  status_changed_at timestamptz not null default now(),
  picked_up_at     timestamptz
);
alter sequence public.order_number_seq owned by public.orders.order_number;
create index on public.orders (pickup_date, status);
create index on public.orders (ip_hash, created_at);
create index on public.orders (lower(last_name));

create table public.order_items (
  id               uuid primary key default gen_random_uuid(),
  order_id         uuid not null references public.orders (id) on delete cascade,
  product_id       uuid not null references public.products (id),
  product_name     text not null,        -- copy of the name at order time
  unit_price_cents int  not null check (unit_price_cents >= 0),
  quantity         int  not null check (quantity > 0)
);
create index on public.order_items (order_id);
create index on public.order_items (product_id);

-- The stock ledger. products.stock always equals the sum of these rows.
create table public.stock_movements (
  id             bigint generated always as identity primary key,
  product_id     uuid not null references public.products (id) on delete cascade,
  change         int  not null check (change <> 0),
  reason         public.movement_reason not null,
  -- The day the change belongs to (Arizona time). Used to line up
  -- online pickups with that day's imported sales.
  effective_date date not null,
  note           text,
  source_id      uuid,   -- the order, import, or expense that caused it (if any)
  created_by     uuid references auth.users (id) on delete set null,
  created_at     timestamptz not null default now(),
  -- Hand-made changes must say why.
  constraint manual_changes_need_a_note check (
    reason not in ('manual_adjustment', 'spoilage') or coalesce(btrim(note), '') <> ''
  )
);
create index on public.stock_movements (product_id, effective_date);
create index on public.stock_movements (source_id);

-- Perishable restocks and their expiration dates. We don't track which exact
-- package was sold; instead the app assumes the oldest batch sells first
-- (see src/lib/calculations.ts → batchesStillOnShelf).
create table public.product_batches (
  id          uuid primary key default gen_random_uuid(),
  product_id  uuid not null references public.products (id) on delete cascade,
  quantity    int  not null check (quantity > 0),
  received_on date not null,
  expires_on  date not null,
  expense_id  uuid,   -- linked after expenses table exists (below)
  created_at  timestamptz not null default now()
);
create index on public.product_batches (product_id, received_on);

-- Shopping trips.
create table public.expenses (
  id           uuid primary key default gen_random_uuid(),
  purchased_on date not null,
  supplier_id  uuid references public.suppliers (id) on delete set null,
  buyer_name   text not null,
  receipt_path text,   -- path inside the private "receipts" bucket
  notes        text,
  total_cents  int  not null default 0 check (total_cents >= 0),
  created_by   uuid references auth.users (id) on delete set null,
  created_at   timestamptz not null default now()
);
create index on public.expenses (purchased_on);

-- Line items on a shopping trip. product_id is empty for supplies that
-- aren't sold (napkins, bags) — they still count as spending.
create table public.expense_items (
  id              uuid primary key default gen_random_uuid(),
  expense_id      uuid not null references public.expenses (id) on delete cascade,
  product_id      uuid references public.products (id) on delete set null,
  description     text not null,
  quantity        int  not null check (quantity > 0),
  unit_cost_cents int  not null check (unit_cost_cents >= 0),
  line_total_cents int generated always as (quantity * unit_cost_cents) stored
);
create index on public.expense_items (expense_id);
create index on public.expense_items (product_id);

alter table public.product_batches
  add constraint product_batches_expense_fk
  foreign key (expense_id) references public.expenses (id) on delete cascade;

-- One uploaded InTouchPay export.
create table public.sales_imports (
  id              uuid primary key default gen_random_uuid(),
  file_name       text not null,
  file_hash       text not null,         -- SHA-256 of the file, to block re-uploading the same file
  column_mapping  jsonb not null default '{}',
  row_count       int  not null default 0,  -- rows in the file
  imported_count  int  not null default 0,  -- rows saved
  duplicate_count int  not null default 0,  -- rows skipped because they were already imported
  date_from       date,
  date_to         date,
  revenue_cents   int  not null default 0,
  imported_by     uuid references auth.users (id) on delete set null,
  created_at      timestamptz not null default now(),
  undone_at       timestamptz,
  undone_by       uuid references auth.users (id) on delete set null
);
-- The same file can't be active twice (it can be re-imported after an undo).
create unique index sales_imports_active_file on public.sales_imports (file_hash) where undone_at is null;

-- One row per line in the export.
create table public.sales_lines (
  id               uuid primary key default gen_random_uuid(),
  import_id        uuid not null references public.sales_imports (id) on delete cascade,
  sold_at          timestamptz,
  sale_date        date not null,
  raw_item_name    text not null,        -- exactly as it appeared in the file
  product_id       uuid references public.products (id) on delete set null, -- empty = unmatched
  quantity         int  not null,        -- negative for refunds
  unit_price_cents int  not null,
  total_cents      int  not null,
  payment_type     public.payment_type not null default 'other',
  transaction_ref  text,
  -- A fingerprint of the line's contents. Unique, so the same sale can never
  -- be imported twice even if it shows up in two different export files.
  fingerprint      text not null unique
);
create index on public.sales_lines (sale_date);
create index on public.sales_lines (product_id, sale_date);
create index on public.sales_lines (import_id);


-- -----------------------------------------------------------------------------
-- 3. Helper functions
-- -----------------------------------------------------------------------------

-- Today's date in the store's timezone.
create or replace function public.store_today()
returns date
language sql stable
set search_path = public
as $$
  select (now() at time zone (select timezone from public.settings where id = 1))::date;
$$;

-- The current time of day in the store's timezone.
create or replace function public.store_now_time()
returns time
language sql stable
set search_path = public
as $$
  select (now() at time zone (select timezone from public.settings where id = 1))::time;
$$;

-- True when the logged-in user is the store admin.
-- SECURITY DEFINER so it can read `admins` even though RLS protects it.
create or replace function public.is_admin()
returns boolean
language sql stable security definer
set search_path = public
as $$
  select exists (select 1 from public.admins where user_id = auth.uid());
$$;

-- Is the store open for pickups on this date? (Not a weekend, not a closed date.)
create or replace function public.is_open_day(d date)
returns boolean
language sql stable
set search_path = public
as $$
  select extract(isodow from d) < 6
     and not exists (select 1 from public.closed_dates where closed_on = d);
$$;

-- The first open day strictly after `d` (looks up to 60 days ahead).
create or replace function public.next_open_day(d date)
returns date
language sql stable
set search_path = public
as $$
  select min(day)::date
  from generate_series(d + 1, d + 60, interval '1 day') as day
  where public.is_open_day(day::date);
$$;

-- Units of each product held by open online orders (today or later).
-- Orders from past days don't count even if nobody closed them yet.
create or replace view public.product_reserved
with (security_invoker = true)
as
  select oi.product_id, sum(oi.quantity)::int as reserved
  from public.order_items oi
  join public.orders o on o.id = oi.order_id
  where o.status in ('received', 'preparing', 'ready')
    and o.pickup_date >= public.store_today()
  group by oi.product_id;


-- -----------------------------------------------------------------------------
-- 4. Triggers
-- -----------------------------------------------------------------------------

-- Every new stock movement updates the product's stock count.
create or replace function public.apply_stock_movement()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  update public.products
     set stock = stock + new.change,
         updated_at = now()
   where id = new.product_id;
  return new;
end;
$$;

create trigger stock_movements_apply
after insert on public.stock_movements
for each row execute function public.apply_stock_movement();

-- Movements are a permanent history: block edits and deletes.
-- (To fix a mistake, add a new movement that reverses it.)
create or replace function public.block_movement_changes()
returns trigger
language plpgsql
as $$
begin
  raise exception 'Stock history cannot be edited. Add a new adjustment instead.';
end;
$$;

create trigger stock_movements_readonly
before update or delete on public.stock_movements
for each row
when (pg_trigger_depth() = 0)  -- allow cascades when a whole product is deleted
execute function public.block_movement_changes();

-- Keep updated_at fresh.
create or replace function public.touch_updated_at()
returns trigger
language plpgsql
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

create trigger products_touch before update on public.products
for each row execute function public.touch_updated_at();
create trigger settings_touch before update on public.settings
for each row execute function public.touch_updated_at();

-- >>>>>>>>>>>>>>>>>>>>>>>> 20261026000002_orders.sql >>>>>>>>>>>>>>>>>>>>>>>>
-- =============================================================================
-- School Store — ordering, stock reconciliation, and public read functions
-- =============================================================================
-- The public (students) never read or write tables directly. They only call
-- these functions:
--   get_menu()             products students can see, with "available" counts
--   get_store_info()       hours, banner, pickup windows, what days are open
--   lookup_order(n, last)  status of one order, needs the matching last name
--   place_order(...)       creates an order (called by the website server only)
--
-- Errors use short codes in the message (e.g. 'SOLD_OUT') and a friendly
-- sentence in the HINT. The website shows the hint to students.
-- =============================================================================


-- -----------------------------------------------------------------------------
-- Public: menu and store info
-- -----------------------------------------------------------------------------

-- Products students can order. Leaves out cost, supplier, and exact stock.
-- `available` = stock − reserved, never below 0.
create or replace function public.get_menu()
returns table (
  id          uuid,
  name        text,
  description text,
  category    text,
  emoji       text,
  photo_path  text,
  price_cents int,
  tags        text[],
  available   int
)
language sql stable security definer
set search_path = public
as $$
  select p.id, p.name, p.description, p.category, p.emoji, p.photo_path,
         p.price_cents, p.tags,
         greatest(p.stock - coalesce(r.reserved, 0), 0) as available
  from public.products p
  left join public.product_reserved r on r.product_id = p.id
  where p.available_online and not p.archived
  order by p.category, p.name;
$$;

-- Everything the public pages need to know about the store, as one JSON object.
create or replace function public.get_store_info()
returns jsonb
language sql stable security definer
set search_path = public
as $$
  select jsonb_build_object(
    'store_name',        s.store_name,
    'store_hours',       s.store_hours,
    'pickup_location',   s.pickup_location,
    'banner_text',       s.banner_text,
    'today',             public.store_today(),
    'now_time',          to_char(public.store_now_time(), 'HH24:MI'),
    'order_cutoff_time', to_char(s.order_cutoff_time, 'HH24:MI'),
    'order_lead_minutes', s.order_lead_minutes,
    'max_items_per_order', s.max_items_per_order,
    'today_is_open',     public.is_open_day(public.store_today()),
    'next_open_day',     public.next_open_day(public.store_today()),
    'pickup_windows', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', w.id,
               'label', w.label,
               'starts_at', to_char(w.starts_at, 'HH24:MI'))
             order by w.sort_order, w.starts_at)
      from public.pickup_windows w where w.active), '[]'::jsonb)
  )
  from public.settings s where s.id = 1;
$$;


-- -----------------------------------------------------------------------------
-- Public: order lookup (order number + last name)
-- -----------------------------------------------------------------------------
-- Returns no rows unless BOTH match, so guessing order numbers reveals nothing.
-- The student's name is not returned.
create or replace function public.lookup_order(p_order_number int, p_last_name text)
returns jsonb
language sql stable security definer
set search_path = public
as $$
  select jsonb_build_object(
    'order_number', o.order_number,
    'status',       o.status,
    'pickup_date',  o.pickup_date,
    'pickup_window', w.label,
    'total_cents',  o.total_cents,
    'created_at',   o.created_at,
    'items', (
      select jsonb_agg(jsonb_build_object(
               'name', oi.product_name,
               'quantity', oi.quantity,
               'unit_price_cents', oi.unit_price_cents)
             order by oi.product_name)
      from public.order_items oi where oi.order_id = o.id)
  )
  from public.orders o
  join public.pickup_windows w on w.id = o.pickup_window_id
  where o.order_number = p_order_number
    and lower(btrim(o.last_name)) = lower(btrim(p_last_name));
$$;


-- -----------------------------------------------------------------------------
-- place_order: the only way an order gets created
-- -----------------------------------------------------------------------------
-- Called by the website's server (with the service role key), never directly
-- from a browser — that's how we know the ip_hash is real and can't be faked.
--
-- p_items is a JSON array: [{"product_id": "...", "quantity": 2}, ...]
--
-- Everything happens in one transaction. Product rows are locked while we
-- check stock, so two students can't both buy the last bag of chips.
create or replace function public.place_order(
  p_first_name       text,
  p_last_name        text,
  p_grade            text,
  p_pickup_window_id int,
  p_pickup_date      date,
  p_items            jsonb,
  p_ip_hash          text
)
returns jsonb
language plpgsql security definer
set search_path = public
as $$
declare
  s            public.settings;
  w            public.pickup_windows;
  v_today      date := public.store_today();
  v_now        time := public.store_now_time();
  v_first      text := btrim(coalesce(p_first_name, ''));
  v_last       text := btrim(coalesce(p_last_name, ''));
  v_grade      text := btrim(coalesce(p_grade, ''));
  v_item       record;
  v_product    public.products;
  v_available  int;
  v_total      int := 0;
  v_count      int;
  v_order      public.orders;
begin
  select * into s from public.settings where id = 1;

  -- ---- Who is ordering --------------------------------------------------------
  if v_first = '' or v_last = '' or v_grade = '' then
    raise exception 'MISSING_INFO' using hint = 'Please fill in your first name, last name, and grade.';
  end if;
  if char_length(v_first) > 40 or char_length(v_last) > 40 or char_length(v_grade) > 20 then
    raise exception 'INFO_TOO_LONG' using hint = 'One of your answers is too long.';
  end if;

  -- ---- When -------------------------------------------------------------------
  -- Students can order for today or for the next open school day.
  if p_pickup_date is null
     or p_pickup_date not in (v_today, public.next_open_day(v_today)) then
    raise exception 'BAD_DATE' using hint = 'Orders can only be placed for today or the next school day.';
  end if;
  if not public.is_open_day(p_pickup_date) then
    raise exception 'STORE_CLOSED' using hint = 'The store is closed that day.';
  end if;

  select * into w from public.pickup_windows where id = p_pickup_window_id and active;
  if not found then
    raise exception 'BAD_WINDOW' using hint = 'Please choose a pickup time.';
  end if;

  if p_pickup_date = v_today then
    if v_now >= s.order_cutoff_time then
      raise exception 'ORDERS_CLOSED' using hint = format(
        'Same-day orders close at %s. You can still order for the next school day.',
        to_char(s.order_cutoff_time, 'FMHH12:MI AM'));
    end if;
    if v_now >= w.starts_at - make_interval(mins => s.order_lead_minutes) then
      raise exception 'WINDOW_CLOSED' using hint = format(
        'It''s too late to order for %s today. Please pick a later time.', w.label);
    end if;
  end if;

  -- ---- Prank protection ---------------------------------------------------------
  -- 1) Limit orders per student per day (same first + last name).
  select count(*) into v_count
  from public.orders
  where pickup_date = p_pickup_date
    and lower(first_name) = lower(v_first)
    and lower(last_name)  = lower(v_last)
    and status not in ('canceled');
  if v_count >= s.max_orders_per_student_day then
    raise exception 'STUDENT_LIMIT' using hint = format(
      'You already have %s order(s) for that day, which is the limit.', v_count);
  end if;

  -- 2) Limit orders per device per hour.
  if p_ip_hash is not null then
    select count(*) into v_count
    from public.orders
    where ip_hash = p_ip_hash and created_at > now() - interval '1 hour';
    if v_count >= s.max_orders_per_hour_per_device then
      raise exception 'RATE_LIMIT' using hint = 'Too many orders from this device. Please try again later.';
    end if;
  end if;

  -- ---- What -------------------------------------------------------------------
  if p_items is null or jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then
    raise exception 'EMPTY_CART' using hint = 'Your cart is empty.';
  end if;

  -- Combine duplicate lines and check quantities.
  drop table if exists _cart;
  create temporary table _cart on commit drop as
    select (x->>'product_id')::uuid as product_id, sum((x->>'quantity')::int)::int as quantity
    from jsonb_array_elements(p_items) as x
    group by 1;

  if exists (select 1 from _cart where quantity is null or quantity < 1) then
    raise exception 'BAD_QUANTITY' using hint = 'Each item needs a quantity of at least 1.';
  end if;
  if (select sum(quantity) from _cart) > s.max_items_per_order then
    raise exception 'TOO_MANY_ITEMS' using hint = format(
      'Orders are limited to %s items.', s.max_items_per_order);
  end if;

  -- Create the order first (total filled in below).
  insert into public.orders (first_name, last_name, grade, pickup_window_id, pickup_date, total_cents, ip_hash)
  values (v_first, v_last, v_grade, w.id, p_pickup_date, 0, p_ip_hash)
  returning * into v_order;

  -- Lock each product (in a fixed order to avoid deadlocks) and check stock.
  for v_item in select * from _cart order by product_id loop
    select * into v_product from public.products where id = v_item.product_id for update;

    if not found or v_product.archived or not v_product.available_online then
      raise exception 'UNAVAILABLE' using hint = 'An item in your cart is no longer available. Please refresh the menu.';
    end if;

    select v_product.stock - coalesce((select reserved from public.product_reserved where product_id = v_product.id), 0)
      into v_available;

    if v_available < v_item.quantity then
      raise exception 'SOLD_OUT' using hint = case
        when v_available <= 0 then format('%s just sold out.', v_product.name)
        else format('Only %s %s left.', v_available, v_product.name) end;
    end if;

    insert into public.order_items (order_id, product_id, product_name, unit_price_cents, quantity)
    values (v_order.id, v_product.id, v_product.name, v_product.price_cents, v_item.quantity);

    v_total := v_total + v_product.price_cents * v_item.quantity;
  end loop;

  update public.orders set total_cents = v_total where id = v_order.id;

  return jsonb_build_object(
    'order_number',  v_order.order_number,
    'pickup_date',   v_order.pickup_date,
    'pickup_window', w.label,
    'total_cents',   v_total
  );
end;
$$;


-- -----------------------------------------------------------------------------
-- Stock reconciliation between online pickups and imported sales
-- -----------------------------------------------------------------------------
-- The rule: stock goes down when an item is paid for.
--   * Online orders are paid at pickup → stock goes down when marked Picked up.
--   * In-person sales only reach us through the InTouchPay import.
--   * BUT online orders are also rung up in InTouchPay, so they appear in the
--     import too. Subtracting both would count them twice.
--
-- So for each product and day:
--     I = units in imported sales that day
--     P = units from online orders picked up that day
--   The import should only subtract what the pickups didn't already:
--     import share = max(0, I − P)
--
-- This function compares that target with what imports have already
-- subtracted for that product/day, and adds one movement for the difference.
-- It's safe to call any number of times (calling it twice changes nothing).
create or replace function public.reconcile_sales_stock(p_product_id uuid, p_day date)
returns void
language plpgsql security definer
set search_path = public
as $$
declare
  v_imported  int;
  v_picked_up int;
  v_target    int;
  v_current   int;
begin
  select coalesce(sum(quantity), 0) into v_imported
  from public.sales_lines
  where product_id = p_product_id and sale_date = p_day;

  select coalesce(-sum(change), 0) into v_picked_up
  from public.stock_movements
  where product_id = p_product_id and effective_date = p_day
    and reason in ('online_pickup', 'online_pickup_undo');

  v_target := greatest(v_imported - v_picked_up, 0);

  select coalesce(-sum(change), 0) into v_current
  from public.stock_movements
  where product_id = p_product_id and effective_date = p_day
    and reason = 'sale_import';

  if v_target <> v_current then
    insert into public.stock_movements (product_id, change, reason, effective_date, note, created_by)
    values (p_product_id, -(v_target - v_current), 'sale_import', p_day,
            format('In-person sales on %s (imported %s, online pickups %s)', p_day, v_imported, v_picked_up),
            auth.uid());
  end if;
end;
$$;


-- -----------------------------------------------------------------------------
-- Staff: change an order's status
-- -----------------------------------------------------------------------------
-- Moving TO picked_up subtracts the items from stock (they've been paid for).
-- Moving AWAY from picked_up (a mistake) puts them back.
create or replace function public.set_order_status(p_order_id uuid, p_status public.order_status)
returns void
language plpgsql security definer
set search_path = public
as $$
declare
  v_order public.orders;
  v_day   date := public.store_today();
  v_item  record;
begin
  if not public.is_admin() then
    raise exception 'NOT_ALLOWED' using hint = 'Only the store admin can do that.';
  end if;

  select * into v_order from public.orders where id = p_order_id for update;
  if not found then
    raise exception 'NOT_FOUND' using hint = 'That order no longer exists.';
  end if;
  if v_order.status = p_status then
    return;
  end if;

  if p_status = 'picked_up' then
    for v_item in select product_id, sum(quantity)::int as qty from public.order_items
                  where order_id = p_order_id group by product_id loop
      insert into public.stock_movements (product_id, change, reason, effective_date, note, source_id, created_by)
      values (v_item.product_id, -v_item.qty, 'online_pickup', v_day,
              format('Online order SS-%s picked up', lpad(v_order.order_number::text, 4, '0')),
              p_order_id, auth.uid());
      perform public.reconcile_sales_stock(v_item.product_id, v_day);
    end loop;

  elsif v_order.status = 'picked_up' then
    -- Undo on the day it was picked up, so the day's math still lines up.
    v_day := (v_order.picked_up_at at time zone (select timezone from public.settings where id = 1))::date;
    for v_item in select product_id, sum(quantity)::int as qty from public.order_items
                  where order_id = p_order_id group by product_id loop
      insert into public.stock_movements (product_id, change, reason, effective_date, note, source_id, created_by)
      values (v_item.product_id, v_item.qty, 'online_pickup_undo', v_day,
              format('Order SS-%s moved back from Picked up', lpad(v_order.order_number::text, 4, '0')),
              p_order_id, auth.uid());
      perform public.reconcile_sales_stock(v_item.product_id, v_day);
    end loop;
  end if;

  update public.orders
     set status = p_status,
         status_changed_at = now(),
         picked_up_at = case when p_status = 'picked_up' then now()
                             when v_order.status = 'picked_up' then null
                             else picked_up_at end
   where id = p_order_id;
end;
$$;


-- -----------------------------------------------------------------------------
-- Scheduled housekeeping (run by pg_cron, see the jobs migration)
-- -----------------------------------------------------------------------------

-- Close orders nobody collected on past days. This releases their reserved
-- stock (reservations only count open orders).
create or replace function public.expire_uncollected_orders()
returns int
language sql security definer
set search_path = public
as $$
  with expired as (
    update public.orders
       set status = 'expired', status_changed_at = now()
     where status in ('received', 'preparing', 'ready')
       and pickup_date < public.store_today()
    returning 1
  )
  select count(*)::int from expired;
$$;

-- Delete orders older than the retention setting (default 90 days).
-- Stock history keeps its rows (they hold no personal info).
create or replace function public.delete_old_orders()
returns int
language sql security definer
set search_path = public
as $$
  with gone as (
    delete from public.orders
     where created_at < now() - make_interval(days => (select order_retention_days from public.settings where id = 1))
    returning 1
  )
  select count(*)::int from gone;
$$;

-- >>>>>>>>>>>>>>>>>>>>>>>> 20261026000003_security.sql >>>>>>>>>>>>>>>>>>>>>>>>
-- =============================================================================
-- School Store — security: Row Level Security, function permissions, storage
-- =============================================================================
-- The short version:
--   * Students (the "anon" role) can't read or write ANY table directly.
--     They can only call get_menu, get_store_info and lookup_order.
--   * place_order can only be called by the website's server (service_role).
--   * The admin (a logged-in user listed in `admins`) can do everything.
-- =============================================================================

-- Turn on RLS for every table. With RLS on and no policy, access is denied.
alter table public.admins           enable row level security;
alter table public.settings         enable row level security;
alter table public.pickup_windows   enable row level security;
alter table public.closed_dates     enable row level security;
alter table public.suppliers        enable row level security;
alter table public.products         enable row level security;
alter table public.product_aliases  enable row level security;
alter table public.orders           enable row level security;
alter table public.order_items      enable row level security;
alter table public.stock_movements  enable row level security;
alter table public.product_batches  enable row level security;
alter table public.expenses         enable row level security;
alter table public.expense_items    enable row level security;
alter table public.sales_imports    enable row level security;
alter table public.sales_lines      enable row level security;

-- One "admin can do anything" policy per table.
do $$
declare
  t text;
begin
  foreach t in array array[
    'settings', 'pickup_windows', 'closed_dates', 'suppliers', 'products',
    'product_aliases', 'orders', 'order_items', 'product_batches',
    'expenses', 'expense_items', 'sales_imports', 'sales_lines'
  ] loop
    execute format(
      'create policy "admin full access" on public.%I for all to authenticated
         using (public.is_admin()) with check (public.is_admin())', t);
  end loop;
end $$;

-- Stock history: admin can read and add, never edit (a trigger also blocks it).
create policy "admin reads stock history" on public.stock_movements
  for select to authenticated using (public.is_admin());
create policy "admin adds stock history" on public.stock_movements
  for insert to authenticated with check (public.is_admin());

-- The admin can see their own row (used to check "am I the admin?").
create policy "admin sees self" on public.admins
  for select to authenticated using (user_id = auth.uid());


-- -----------------------------------------------------------------------------
-- Function permissions
-- -----------------------------------------------------------------------------
-- Postgres lets everyone run new functions by default. Take that away, then
-- give back exactly what each role needs.
revoke execute on all functions in schema public from public, anon, authenticated;

-- Students (and everyone else)
grant execute on function public.get_menu()                to anon, authenticated;
grant execute on function public.get_store_info()          to anon, authenticated;
grant execute on function public.lookup_order(int, text)   to anon, authenticated;

-- Small date helpers (harmless; they reveal nothing private).
grant execute on function public.store_today()        to anon, authenticated, service_role;
grant execute on function public.store_now_time()     to anon, authenticated, service_role;
grant execute on function public.is_open_day(date)    to anon, authenticated, service_role;
grant execute on function public.next_open_day(date)  to anon, authenticated, service_role;

-- Used inside RLS policies, so the logged-in user must be able to run it.
grant execute on function public.is_admin()           to authenticated;

-- Staff actions (each one also checks is_admin() inside)
grant execute on function public.set_order_status(uuid, public.order_status) to authenticated;
-- reconcile_sales_stock is only called from inside other functions.

-- The website server only
grant execute on function public.place_order(text, text, text, int, date, jsonb, text) to service_role;
grant execute on function public.expire_uncollected_orders() to service_role;
grant execute on function public.delete_old_orders()         to service_role;

-- Future functions start locked down too.
alter default privileges in schema public revoke execute on functions from public, anon, authenticated;

-- The reserved-stock view is for the admin only.
revoke all on public.product_reserved from anon;


-- -----------------------------------------------------------------------------
-- File storage
-- -----------------------------------------------------------------------------
-- product-photos: anyone can view (they're on the menu); only the admin uploads.
-- receipts:       private; only the admin can view or upload.
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values
  ('product-photos', 'product-photos', true,  5242880,  array['image/jpeg', 'image/png', 'image/webp']),
  ('receipts',       'receipts',       false, 10485760, array['image/jpeg', 'image/png', 'image/webp', 'image/heic', 'application/pdf'])
on conflict (id) do nothing;

create policy "admin manages product photos" on storage.objects
  for all to authenticated
  using (bucket_id = 'product-photos' and public.is_admin())
  with check (bucket_id = 'product-photos' and public.is_admin());

create policy "admin manages receipts" on storage.objects
  for all to authenticated
  using (bucket_id = 'receipts' and public.is_admin())
  with check (bucket_id = 'receipts' and public.is_admin());

-- >>>>>>>>>>>>>>>>>>>>>>>> 20261026000004_scheduled_jobs.sql >>>>>>>>>>>>>>>>>>>>>>>>
-- =============================================================================
-- School Store — scheduled jobs (pg_cron)
-- =============================================================================
-- pg_cron runs SQL on a schedule inside the database. It's included free with
-- Supabase. Times are in UTC. Arizona is always UTC−7 (no daylight saving),
-- so 06:00 UTC = 11:00 PM in Arizona.
--
-- To see the jobs:   select * from cron.job;
-- To see past runs:  select * from cron.job_run_details order by start_time desc;
-- =============================================================================

do $$
begin
  if exists (select 1 from pg_available_extensions where name = 'pg_cron') then
    create extension if not exists pg_cron;

    -- Every night at 11:00 PM Arizona: close orders nobody picked up.
    perform cron.schedule(
      'expire-uncollected-orders',
      '0 6 * * *',
      'select public.expire_uncollected_orders();'
    );

    -- Every night at 11:30 PM Arizona: delete orders past the retention period.
    perform cron.schedule(
      'delete-old-orders',
      '30 6 * * *',
      'select public.delete_old_orders();'
    );
  else
    raise notice 'pg_cron is not available here; skipping scheduled jobs.';
  end if;
end $$;

-- >>>>>>>>>>>>>>>>>>>>>>>> 20261026000005_dashboard.sql >>>>>>>>>>>>>>>>>>>>>>>>
-- =============================================================================
-- School Store — numbers for the staff dashboard, in one call
-- =============================================================================

create or replace function public.dashboard_summary()
returns jsonb
language plpgsql stable security definer
set search_path = public
as $$
declare
  v_today date := public.store_today();
  -- Monday of this week
  v_week_start date := v_today - (extract(isodow from v_today)::int - 1);
  v_result jsonb;
begin
  if not public.is_admin() then
    raise exception 'NOT_ALLOWED' using hint = 'Only the store admin can do that.';
  end if;

  select jsonb_build_object(
    'today', v_today,
    'week_start', v_week_start,

    -- {"received": 4, "ready": 2, ...} for orders picked up today
    'orders_today', coalesce((
      select jsonb_object_agg(status, n)
      from (select status, count(*) as n from public.orders
            where pickup_date = v_today group by status) t), '{}'::jsonb),

    'orders_upcoming', (
      select count(*) from public.orders
      where pickup_date > v_today and status in ('received', 'preparing', 'ready')),

    'week_revenue_cents', (
      select coalesce(sum(total_cents), 0) from public.sales_lines
      where sale_date between v_week_start and v_today),

    'week_spending_cents', (
      select coalesce(sum(total_cents), 0) from public.expenses
      where purchased_on between v_week_start and v_today),

    'last_week_revenue_cents', (
      select coalesce(sum(total_cents), 0) from public.sales_lines
      where sale_date between v_week_start - 7 and v_week_start - 1),

    'last_week_spending_cents', (
      select coalesce(sum(total_cents), 0) from public.expenses
      where purchased_on between v_week_start - 7 and v_week_start - 1),

    'last_import_at', (
      select max(created_at) from public.sales_imports where undone_at is null),

    'last_sale_date', (
      select max(sale_date) from public.sales_lines),

    'unmatched_sales_lines', (
      select count(*) from public.sales_lines where product_id is null),

    -- Products at or below their reorder point, most urgent first.
    'low_stock', coalesce((
      select jsonb_agg(row_to_json(t) order by t.stock - t.reorder_point, t.name)
      from (
        select p.id, p.name, p.emoji, p.stock, p.reorder_point,
               coalesce(r.reserved, 0) as reserved
        from public.products p
        left join public.product_reserved r on r.product_id = p.id
        where not p.archived and p.stock - coalesce(r.reserved, 0) <= p.reorder_point
      ) t), '[]'::jsonb),

    -- Perishable batches expiring in the next 3 days (may already be sold).
    'expiring_soon', (
      select count(*) from public.product_batches b
      join public.products p on p.id = b.product_id
      where not p.archived and p.stock > 0
        and b.expires_on between v_today and v_today + 3)
  ) into v_result;

  return v_result;
end;
$$;

revoke execute on function public.dashboard_summary() from public, anon;
grant execute on function public.dashboard_summary() to authenticated;

-- >>>>>>>>>>>>>>>>>>>>>>>> 20261026000006_inventory_expenses.sql >>>>>>>>>>>>>>>>>>>>>>>>
-- =============================================================================
-- School Store — inventory numbers and shopping trips (phase 4)
-- =============================================================================
--   inventory_snapshot()   everything the Inventory page needs, in one call
--   save_expense(json)     records a shopping trip and adds the stock
--   delete_expense(id)     removes a trip that was entered by mistake
-- =============================================================================


-- -----------------------------------------------------------------------------
-- inventory_snapshot
-- -----------------------------------------------------------------------------
-- "Units sold" counts every unit that was PAID FOR (online pickups and
-- imported in-person sales), read from the stock history. The averaging
-- window is the sales_average_days setting, shortened if the store doesn't
-- have that much history yet (so a new store isn't under-counted).
create or replace function public.inventory_snapshot()
returns jsonb
language plpgsql stable security definer
set search_path = public
as $$
declare
  s            public.settings;
  v_today      date := public.store_today();
  v_first_sale date;
  v_days       int;
begin
  if not public.is_admin() then
    raise exception 'NOT_ALLOWED' using hint = 'Only the store admin can do that.';
  end if;

  select * into s from public.settings where id = 1;

  select min(effective_date) into v_first_sale
  from public.stock_movements
  where reason in ('sale_import', 'online_pickup');

  v_days := greatest(1, least(s.sales_average_days, v_today - coalesce(v_first_sale, v_today) + 1));

  return jsonb_build_object(
    'today', v_today,
    'window_days', v_days,
    'reorder_buffer_days', s.reorder_buffer_days,
    'shopping_interval_days', s.shopping_interval_days,
    'next_shopping_date', s.next_shopping_date,
    'products', coalesce((
      select jsonb_agg(row_to_json(t) order by t.name)
      from (
        select
          p.id, p.name, p.category, p.emoji, p.photo_path,
          p.stock, coalesce(r.reserved, 0) as reserved,
          p.price_cents, p.unit_cost_cents, p.reorder_point, p.lead_days,
          p.is_perishable, p.available_online,
          sup.name as supplier,
          -- units paid for in the window
          coalesce((
            select -sum(m.change)
            from public.stock_movements m
            where m.product_id = p.id
              and m.reason in ('sale_import', 'online_pickup', 'online_pickup_undo')
              and m.effective_date > v_today - v_days
          ), 0)::int as units_sold,
          -- perishable batches, newest first (for expiration dates)
          case when p.is_perishable then coalesce((
            select jsonb_agg(jsonb_build_object(
                     'quantity', b.quantity, 'received_on', b.received_on, 'expires_on', b.expires_on)
                   order by b.received_on desc, b.created_at desc)
            from public.product_batches b where b.product_id = p.id
          ), '[]'::jsonb) end as batches
        from public.products p
        left join public.product_reserved r on r.product_id = p.id
        left join public.suppliers sup on sup.id = p.supplier_id
        where not p.archived
      ) t), '[]'::jsonb)
  );
end;
$$;


-- -----------------------------------------------------------------------------
-- save_expense
-- -----------------------------------------------------------------------------
-- p is a JSON object:
-- {
--   "purchased_on": "2026-10-26", "supplier_id": "...", "buyer_name": "Ms. A",
--   "receipt_path": "2026/10/abc.jpg", "notes": "...",
--   "items": [
--     { "product_id": "...", "description": "Hot Cheetos", "quantity": 24,
--       "unit_cost_cents": 55, "update_cost": true, "expires_on": null },
--     { "product_id": null, "description": "Napkins", "quantity": 1, "unit_cost_cents": 649 }
--   ]
-- }
-- Everything happens together: if any line is bad, nothing is saved.
create or replace function public.save_expense(p jsonb)
returns uuid
language plpgsql security definer
set search_path = public
as $$
declare
  v_id      uuid;
  v_item    jsonb;
  v_product public.products;
  v_qty     int;
  v_cost    int;
  v_date    date := (p->>'purchased_on')::date;
begin
  if not public.is_admin() then
    raise exception 'NOT_ALLOWED' using hint = 'Only the store admin can do that.';
  end if;
  if v_date is null or v_date > public.store_today() then
    raise exception 'BAD_DATE' using hint = 'Choose the day of the trip (it can''t be in the future).';
  end if;
  if coalesce(btrim(p->>'buyer_name'), '') = '' then
    raise exception 'NO_BUYER' using hint = 'Enter who did the shopping.';
  end if;
  if jsonb_typeof(p->'items') <> 'array' or jsonb_array_length(p->'items') = 0 then
    raise exception 'NO_ITEMS' using hint = 'Add at least one item.';
  end if;

  insert into public.expenses (purchased_on, supplier_id, buyer_name, receipt_path, notes, created_by)
  values (v_date, nullif(p->>'supplier_id', '')::uuid, btrim(p->>'buyer_name'),
          nullif(p->>'receipt_path', ''), nullif(btrim(p->>'notes'), ''), auth.uid())
  returning id into v_id;

  for v_item in select * from jsonb_array_elements(p->'items') loop
    v_qty  := (v_item->>'quantity')::int;
    v_cost := (v_item->>'unit_cost_cents')::int;
    if v_qty is null or v_qty < 1 or v_cost is null or v_cost < 0 then
      raise exception 'BAD_LINE' using hint = 'Every line needs a quantity of 1 or more and a cost.';
    end if;

    v_product := null;
    if nullif(v_item->>'product_id', '') is not null then
      select * into v_product from public.products where id = (v_item->>'product_id')::uuid;
      if not found then
        raise exception 'BAD_PRODUCT' using hint = 'One of the products no longer exists.';
      end if;
    end if;

    insert into public.expense_items (expense_id, product_id, description, quantity, unit_cost_cents)
    values (v_id, v_product.id,
            coalesce(nullif(btrim(v_item->>'description'), ''), v_product.name, 'Supplies'),
            v_qty, v_cost);

    if v_product.id is not null then
      -- Add to stock.
      insert into public.stock_movements (product_id, change, reason, effective_date, note, source_id, created_by)
      values (v_product.id, v_qty, 'restock', v_date, 'Shopping trip', v_id, auth.uid());

      -- Remember the expiration date for perishables.
      if v_product.is_perishable and nullif(v_item->>'expires_on', '') is not null then
        insert into public.product_batches (product_id, quantity, received_on, expires_on, expense_id)
        values (v_product.id, v_qty, v_date, (v_item->>'expires_on')::date, v_id);
      end if;

      -- Optionally update the product's cost to this trip's price.
      if coalesce((v_item->>'update_cost')::boolean, false) then
        update public.products set unit_cost_cents = v_cost where id = v_product.id;
      end if;
    end if;
  end loop;

  update public.expenses e
     set total_cents = (select coalesce(sum(line_total_cents), 0) from public.expense_items where expense_id = e.id)
   where e.id = v_id;

  return v_id;
end;
$$;


-- -----------------------------------------------------------------------------
-- delete_expense
-- -----------------------------------------------------------------------------
-- For trips entered by mistake. Takes back the stock it added (as a new
-- history line, so the history stays honest), then deletes the trip.
-- Product costs that were updated are NOT changed back.
create or replace function public.delete_expense(p_expense_id uuid)
returns text
language plpgsql security definer
set search_path = public
as $$
declare
  v_receipt text;
begin
  if not public.is_admin() then
    raise exception 'NOT_ALLOWED' using hint = 'Only the store admin can do that.';
  end if;

  select receipt_path into v_receipt from public.expenses where id = p_expense_id;
  if not found then
    raise exception 'NOT_FOUND' using hint = 'That shopping trip no longer exists.';
  end if;

  insert into public.stock_movements (product_id, change, reason, effective_date, note, source_id, created_by)
  select m.product_id, -sum(m.change)::int, 'manual_adjustment', public.store_today(),
         'Shopping trip deleted (entered by mistake)', p_expense_id, auth.uid()
  from public.stock_movements m
  where m.source_id = p_expense_id and m.reason = 'restock'
  group by m.product_id
  having sum(m.change) <> 0;

  delete from public.expenses where id = p_expense_id;  -- items and batches go with it

  return v_receipt;  -- so the website can delete the receipt file too
end;
$$;


revoke execute on function public.inventory_snapshot()   from public, anon;
revoke execute on function public.save_expense(jsonb)    from public, anon;
revoke execute on function public.delete_expense(uuid)   from public, anon;
grant  execute on function public.inventory_snapshot()   to authenticated;
grant  execute on function public.save_expense(jsonb)    to authenticated;
grant  execute on function public.delete_expense(uuid)   to authenticated;

-- >>>>>>>>>>>>>>>>>>>>>>>> 20261026000007_sales_import.sql >>>>>>>>>>>>>>>>>>>>>>>>
-- =============================================================================
-- School Store — importing the InTouchPay sales export (phase 5)
-- =============================================================================
--   import_sales(json)        saves one uploaded file's sales, all or nothing
--   undo_import(id)           removes an import's sales and fixes stock
--   link_item_name(name, id)  "this InTouchPay name is that product"
--   unmatched_item_names()    sales whose item name isn't linked to a product
--
-- After any of these, stock is corrected with reconcile_sales_stock() for
-- each product + day that changed (see the orders migration for how that
-- avoids counting online orders twice).
-- =============================================================================


-- Re-runs the stock math for a list of (product, day) pairs.
create or replace function public.reconcile_pairs(p_pairs jsonb)
returns void
language plpgsql security definer
set search_path = public
as $$
declare
  v_pair record;
begin
  for v_pair in
    select distinct (x->>'product_id')::uuid as product_id, (x->>'sale_date')::date as sale_date
    from jsonb_array_elements(p_pairs) x
    where x->>'product_id' is not null
  loop
    perform public.reconcile_sales_stock(v_pair.product_id, v_pair.sale_date);
  end loop;
end;
$$;


-- -----------------------------------------------------------------------------
-- import_sales
-- -----------------------------------------------------------------------------
-- p = {
--   "file_name": "export.csv", "file_hash": "<sha-256>", "row_count": 120,
--   "column_mapping": { ... },
--   "aliases": [ { "alias": "fruit snacks", "product_id": "..." } ],   -- new links to remember
--   "lines": [ { "sold_at": "2026-10-26T12:30:00-07:00", "sale_date": "2026-10-26",
--                "raw_item_name": "HOT CHEETOS 1OZ", "product_id": "..." | null,
--                "quantity": 2, "unit_price_cents": 150, "total_cents": 300,
--                "payment_type": "cash", "transaction_ref": "T123", "fingerprint": "..." } ]
-- }
-- Lines whose fingerprint was already imported are skipped (duplicate
-- protection), so overlapping exports are safe to upload.
create or replace function public.import_sales(p jsonb)
returns jsonb
language plpgsql security definer
set search_path = public
as $$
declare
  v_id        uuid;
  v_inserted  int;
  v_total     int := jsonb_array_length(p->'lines');
  v_pairs     jsonb;
begin
  if not public.is_admin() then
    raise exception 'NOT_ALLOWED' using hint = 'Only the store admin can do that.';
  end if;
  if v_total = 0 then
    raise exception 'NO_LINES' using hint = 'There are no sales lines to import.';
  end if;
  if exists (select 1 from public.sales_imports where file_hash = p->>'file_hash' and undone_at is null) then
    raise exception 'DUPLICATE_FILE' using hint = 'This exact file was already imported. Nothing was added.';
  end if;

  -- Remember new InTouchPay names (so next time they match by themselves).
  insert into public.product_aliases (product_id, alias)
  select (a->>'product_id')::uuid, lower(btrim(a->>'alias'))
  from jsonb_array_elements(coalesce(p->'aliases', '[]'::jsonb)) a
  where nullif(a->>'product_id', '') is not null and btrim(a->>'alias') <> ''
  on conflict (alias) do update set product_id = excluded.product_id;

  insert into public.sales_imports (file_name, file_hash, column_mapping, row_count, imported_by)
  values (p->>'file_name', p->>'file_hash', coalesce(p->'column_mapping', '{}'::jsonb),
          coalesce((p->>'row_count')::int, v_total), auth.uid())
  returning id into v_id;

  with incoming as (
    select
      nullif(l->>'sold_at', '')::timestamptz as sold_at,
      (l->>'sale_date')::date as sale_date,
      l->>'raw_item_name' as raw_item_name,
      -- use the link chosen in the preview, or a saved name, or the product's own name
      coalesce(
        nullif(l->>'product_id', '')::uuid,
        (select pa.product_id from public.product_aliases pa where pa.alias = lower(btrim(l->>'raw_item_name'))),
        (select pr.id from public.products pr where lower(pr.name) = lower(btrim(l->>'raw_item_name')) limit 1)
      ) as product_id,
      (l->>'quantity')::int as quantity,
      (l->>'unit_price_cents')::int as unit_price_cents,
      (l->>'total_cents')::int as total_cents,
      coalesce(nullif(l->>'payment_type', ''), 'other')::public.payment_type as payment_type,
      nullif(l->>'transaction_ref', '') as transaction_ref,
      l->>'fingerprint' as fingerprint
    from jsonb_array_elements(p->'lines') l
  ),
  inserted as (
    insert into public.sales_lines (import_id, sold_at, sale_date, raw_item_name, product_id, quantity,
                                    unit_price_cents, total_cents, payment_type, transaction_ref, fingerprint)
    select v_id, sold_at, sale_date, raw_item_name, product_id, quantity,
           unit_price_cents, total_cents, payment_type, transaction_ref, fingerprint
    from incoming
    on conflict (fingerprint) do nothing
    returning product_id, sale_date
  )
  select count(*)::int,
         coalesce(jsonb_agg(distinct jsonb_build_object('product_id', product_id, 'sale_date', sale_date))
                  filter (where product_id is not null), '[]'::jsonb)
  into v_inserted, v_pairs
  from inserted;

  if v_inserted = 0 then
    -- Everything was a duplicate: don't keep an empty import in the history.
    delete from public.sales_imports where id = v_id;
    raise exception 'ALL_DUPLICATES' using hint = 'Every sale in this file was already imported. Nothing was added.';
  end if;

  perform public.reconcile_pairs(v_pairs);

  update public.sales_imports si set
    imported_count  = v_inserted,
    duplicate_count = v_total - v_inserted,
    date_from       = (select min(sale_date) from public.sales_lines where import_id = v_id),
    date_to         = (select max(sale_date) from public.sales_lines where import_id = v_id),
    revenue_cents   = (select coalesce(sum(total_cents), 0) from public.sales_lines where import_id = v_id)
  where si.id = v_id;

  return jsonb_build_object(
    'import_id', v_id,
    'imported', v_inserted,
    'duplicates', v_total - v_inserted,
    'unmatched', (select count(*) from public.sales_lines where import_id = v_id and product_id is null)
  );
end;
$$;


-- -----------------------------------------------------------------------------
-- undo_import
-- -----------------------------------------------------------------------------
-- Deletes the import's sales lines (so the same file can be imported again
-- later), keeps the import in the history marked "undone", and fixes stock.
create or replace function public.undo_import(p_import_id uuid)
returns void
language plpgsql security definer
set search_path = public
as $$
declare
  v_pairs jsonb;
begin
  if not public.is_admin() then
    raise exception 'NOT_ALLOWED' using hint = 'Only the store admin can do that.';
  end if;
  if not exists (select 1 from public.sales_imports where id = p_import_id and undone_at is null) then
    raise exception 'NOT_FOUND' using hint = 'That import was already undone or doesn''t exist.';
  end if;

  select coalesce(jsonb_agg(distinct jsonb_build_object('product_id', product_id, 'sale_date', sale_date))
                  filter (where product_id is not null), '[]'::jsonb)
    into v_pairs
  from public.sales_lines where import_id = p_import_id;

  delete from public.sales_lines where import_id = p_import_id;

  update public.sales_imports
     set undone_at = now(), undone_by = auth.uid()
   where id = p_import_id;

  perform public.reconcile_pairs(v_pairs);
end;
$$;


-- -----------------------------------------------------------------------------
-- link_item_name
-- -----------------------------------------------------------------------------
-- Links every past sale with this InTouchPay item name to a product,
-- remembers the name for future imports, and fixes stock for those days.
create or replace function public.link_item_name(p_raw_name text, p_product_id uuid)
returns int
language plpgsql security definer
set search_path = public
as $$
declare
  v_pairs jsonb;
  v_count int;
begin
  if not public.is_admin() then
    raise exception 'NOT_ALLOWED' using hint = 'Only the store admin can do that.';
  end if;

  insert into public.product_aliases (product_id, alias)
  values (p_product_id, lower(btrim(p_raw_name)))
  on conflict (alias) do update set product_id = excluded.product_id;

  with changed as (
    update public.sales_lines
       set product_id = p_product_id
     where product_id is null
       and lower(btrim(raw_item_name)) = lower(btrim(p_raw_name))
    returning product_id, sale_date
  )
  select count(*)::int,
         coalesce(jsonb_agg(distinct jsonb_build_object('product_id', product_id, 'sale_date', sale_date)), '[]'::jsonb)
    into v_count, v_pairs
  from changed;

  perform public.reconcile_pairs(v_pairs);
  return v_count;
end;
$$;


-- Item names in imported sales that aren't linked to a product yet.
create or replace function public.unmatched_item_names()
returns table (raw_item_name text, lines int, units int, revenue_cents int, last_sold date)
language sql stable security definer
set search_path = public
as $$
  select min(raw_item_name), count(*)::int, sum(quantity)::int, sum(total_cents)::int, max(sale_date)
  from public.sales_lines
  where product_id is null and public.is_admin()
  group by lower(btrim(raw_item_name))
  order by sum(total_cents) desc;
$$;


-- Fingerprints already in the database (for the "already imported" count in the preview).
create or replace function public.existing_fingerprints(p_fingerprints text[])
returns setof text
language sql stable security definer
set search_path = public
as $$
  select fingerprint from public.sales_lines
  where fingerprint = any(p_fingerprints) and public.is_admin();
$$;


revoke execute on function public.reconcile_pairs(jsonb)          from public, anon, authenticated;
revoke execute on function public.import_sales(jsonb)             from public, anon;
revoke execute on function public.undo_import(uuid)               from public, anon;
revoke execute on function public.link_item_name(text, uuid)      from public, anon;
revoke execute on function public.unmatched_item_names()          from public, anon;
revoke execute on function public.existing_fingerprints(text[])   from public, anon;
grant  execute on function public.import_sales(jsonb)             to authenticated;
grant  execute on function public.undo_import(uuid)               to authenticated;
grant  execute on function public.link_item_name(text, uuid)      to authenticated;
grant  execute on function public.unmatched_item_names()          to authenticated;
grant  execute on function public.existing_fingerprints(text[])   to authenticated;

-- >>>>>>>>>>>>>>>>>>>>>>>> 20261026000008_insights.sql >>>>>>>>>>>>>>>>>>>>>>>>
-- =============================================================================
-- School Store — numbers for the Insights page (phase 6)
-- =============================================================================
-- insights(from, to, bucket) returns everything the page shows for one date
-- range, as JSON. `bucket` ('day', 'week' or 'month') sets the size of each
-- bar in the trend chart.
--
-- Where each number comes from:
--   revenue     imported InTouchPay sales (online orders are included, since
--               they're rung up at pickup)
--   spending    shopping trips (expenses)
--   profit      revenue − spending (cash in minus cash out for the range)
--   gross profit  per product: revenue − units sold × the product's cost
--   units paid  stock that left because it was paid for (online pickups +
--               imported in-person sales), from the stock history
-- =============================================================================

create or replace function public.insights(p_from date, p_to date, p_bucket text default 'week')
returns jsonb
language plpgsql stable security definer
set search_path = public
as $$
declare
  v_days       int := p_to - p_from + 1;
  v_prev_from  date := p_from - (p_to - p_from + 1);
  v_prev_to    date := p_from - 1;
  v_bucket     text := case when p_bucket in ('day', 'week', 'month') then p_bucket else 'week' end;
begin
  if not public.is_admin() then
    raise exception 'NOT_ALLOWED' using hint = 'Only the store admin can do that.';
  end if;
  if p_from is null or p_to is null or p_to < p_from then
    raise exception 'BAD_RANGE' using hint = 'Choose a start date before the end date.';
  end if;
  if v_days > 1100 then
    raise exception 'BAD_RANGE' using hint = 'Choose a range of three years or less.';
  end if;

  return jsonb_build_object(
    'from', p_from,
    'to', p_to,
    'bucket', v_bucket,

    -- ---- Headline numbers, this range and the one before it ----
    'totals', (
      select jsonb_build_object(
        'revenue_cents',      (select coalesce(sum(total_cents), 0) from sales_lines where sale_date between p_from and p_to),
        'spending_cents',     (select coalesce(sum(total_cents), 0) from expenses where purchased_on between p_from and p_to),
        'gross_profit_cents', (select coalesce(sum(sl.total_cents - sl.quantity * p.unit_cost_cents), 0)
                               from sales_lines sl join products p on p.id = sl.product_id
                               where sl.sale_date between p_from and p_to),
        'transactions',       (select count(distinct coalesce(transaction_ref, id::text)) from sales_lines where sale_date between p_from and p_to),
        'units_sold',         (select coalesce(sum(quantity), 0) from sales_lines where sale_date between p_from and p_to),
        'online_orders',      (select count(distinct source_id) from stock_movements
                               where reason = 'online_pickup' and effective_date between p_from and p_to),
        'last_sale_date',     (select max(sale_date) from sales_lines)
      )
    ),
    'previous', (
      select jsonb_build_object(
        'from', v_prev_from,
        'to', v_prev_to,
        'revenue_cents',  (select coalesce(sum(total_cents), 0) from sales_lines where sale_date between v_prev_from and v_prev_to),
        'spending_cents', (select coalesce(sum(total_cents), 0) from expenses where purchased_on between v_prev_from and v_prev_to),
        'gross_profit_cents', (select coalesce(sum(sl.total_cents - sl.quantity * p.unit_cost_cents), 0)
                               from sales_lines sl join products p on p.id = sl.product_id
                               where sl.sale_date between v_prev_from and v_prev_to),
        'units_sold',     (select coalesce(sum(quantity), 0) from sales_lines where sale_date between v_prev_from and v_prev_to)
      )
    ),

    -- ---- Trend: one row per day / week / month ----
    'series', (
      select coalesce(jsonb_agg(jsonb_build_object(
               'start', b.start,
               'revenue_cents', coalesce(r.cents, 0),
               'spending_cents', coalesce(e.cents, 0)) order by b.start), '[]'::jsonb)
      from (
        -- A bar never starts before the range (e.g. October's first week starts Oct 1).
        select distinct greatest(date_trunc(v_bucket, d)::date, p_from) as start
        from generate_series(p_from, p_to, interval '1 day') d
      ) b
      left join (
        select greatest(date_trunc(v_bucket, sale_date)::date, p_from) as start, sum(total_cents) as cents
        from sales_lines where sale_date between p_from and p_to group by 1
      ) r on r.start = b.start
      left join (
        select greatest(date_trunc(v_bucket, purchased_on)::date, p_from) as start, sum(total_cents) as cents
        from expenses where purchased_on between p_from and p_to group by 1
      ) e on e.start = b.start
    ),

    -- ---- How people paid ----
    'payments', (
      select coalesce(jsonb_object_agg(payment_type, cents), '{}'::jsonb)
      from (select payment_type, sum(total_cents) as cents from sales_lines
            where sale_date between p_from and p_to group by 1) t
    ),

    -- ---- Online vs in person, in units paid for ----
    'channels', (
      select jsonb_build_object(
        'online_units',  coalesce(-sum(change) filter (where reason in ('online_pickup', 'online_pickup_undo')), 0),
        'total_units',   coalesce(-sum(change), 0)
      )
      from stock_movements
      where reason in ('online_pickup', 'online_pickup_undo', 'sale_import')
        and effective_date between p_from and p_to
    ),

    -- ---- Spending by store ----
    'suppliers', (
      select coalesce(jsonb_agg(jsonb_build_object('name', name, 'cents', cents, 'trips', trips) order by cents desc), '[]'::jsonb)
      from (
        select coalesce(s.name, 'No store') as name, sum(e.total_cents) as cents, count(*) as trips
        from expenses e left join suppliers s on s.id = e.supplier_id
        where e.purchased_on between p_from and p_to
        group by 1
      ) t
    ),

    -- ---- Every product: units, revenue, margin, sell-through ----
    'products', (
      select coalesce(jsonb_agg(row_to_json(t) order by t.revenue_cents desc, t.name), '[]'::jsonb)
      from (
        select
          p.id, p.name, p.category, p.emoji, p.archived,
          p.price_cents, p.unit_cost_cents, p.stock,
          coalesce(s.units, 0)::int as units,
          coalesce(s.revenue, 0)::int as revenue_cents,
          (coalesce(s.revenue, 0) - coalesce(s.units, 0) * p.unit_cost_cents)::int as gross_profit_cents,
          -- Stock before the range, plus what was bought during it = what was available to sell.
          coalesce((select sum(change) from stock_movements m
                    where m.product_id = p.id and m.effective_date < p_from), 0)::int as start_stock,
          coalesce((select sum(change) from stock_movements m
                    where m.product_id = p.id and m.reason = 'restock'
                      and m.effective_date between p_from and p_to), 0)::int as restocked,
          coalesce((select -sum(change) from stock_movements m
                    where m.product_id = p.id
                      and m.reason in ('sale_import', 'online_pickup', 'online_pickup_undo')
                      and m.effective_date between p_from and p_to), 0)::int as units_paid
        from products p
        left join (
          select product_id, sum(quantity) as units, sum(total_cents) as revenue
          from sales_lines where sale_date between p_from and p_to and product_id is not null
          group by product_id
        ) s on s.product_id = p.id
        where not p.archived or s.units is not null
      ) t
    ),

    -- Sales that aren't linked to a product (they count in revenue only).
    'unmatched_revenue_cents', (
      select coalesce(sum(total_cents), 0) from sales_lines
      where sale_date between p_from and p_to and product_id is null
    )
  );
end;
$$;

revoke execute on function public.insights(date, date, text) from public, anon;
grant  execute on function public.insights(date, date, text) to authenticated;

-- >>>>>>>>>>>>>>>>>>>>>>>> seed.sql (sample data) >>>>>>>>>>>>>>>>>>>>>>>>
-- =============================================================================
-- School Store — sample data for testing
-- =============================================================================
-- Creates ~4 weeks of realistic history ending TODAY, so the dashboard and
-- charts look real whenever you run it:
--   * 20 products with InTouchPay alias names
--   * weekly shopping trips (expenses) that restock inventory
--   * one sales import of in-person + online sales for past school days
--   * online orders: past ones picked up, today's in every status
--
-- The numbers are random but repeatable (same seed = same data).
-- Safe to run only on an EMPTY database (e.g. after `supabase db reset`).
-- =============================================================================

do $$ begin perform setseed(0.42); end $$;  -- repeatable random numbers

